\subsection{Definitions and mathematical statement}
\paragraph{Shared notation.}$\mathbb N$, $\mathbb Z$, $\mathbb Q$, $\mathbb R$, and $\mathbb C$ denote the natural numbers, integers, rationals, reals, and complex numbers, respectively. All additional parameters and hypotheses are specified in the question.


\paragraph{Statement recorded in the supplied source.}
For every convex body $K\subseteq\mathbb R^n$, is its Mahler volume bounded by

$$\bar s(K)=\lvert K\rvert\inf_{x\in K}\lvert(K-x)^\circ\rvert\geq\frac{(n+1)^{n+1}}{(n!)^2},$$

with equality for a simplex?
\par\smallskip\textit{Formulation references:} \href{https://huggingface.co/datasets/ulamai/UnsolvedMath}{[S1]}, \href{https://doi.org/10.4171/owr/2018/54}{[S2]}.

\subsection{Short English statement}
For every convex body $K\subseteq\mathbb R^n$, is its Mahler volume bounded by

$$\bar s(K)=\lvert K\rvert\inf_{x\in K}\lvert(K-x)^\circ\rvert\geq\frac{(n+1)^{n+1}}{(n!)^2},$$

with equality for a simplex?

\subsection{Sources}
\begin{itemize}
\item[S1] ULAM.AI and the UnsolvedMath Contributors, UnsolvedMath: A Curated Collection of Open Mathematics Problems, record 30004025 (OWR-16637-003). Catalogue attribution under CC BY 4.0.
\url{https://huggingface.co/datasets/ulamai/UnsolvedMath}.
\item[S2] Original problem formulation and mathematical context.
\url{https://doi.org/10.4171/owr/2018/54}.
\end{itemize}
\label{end:30004025}

